class_name DungeonNavigator
extends RefCounted

var current_room: String = "entrance"


func get_room_name() -> String:
	if current_room == "entrance":
		return "Ingresso della Fortezza"
	elif current_room == "hall":
		return "Grande Atrio"
	elif current_room == "armory":
		return "Armeria Reale"
	elif current_room == "library":
		return "Antica Biblioteca"
	elif current_room == "treasury":
		return "Sala del Tesoro"
	return "Stanza Sconosciuta"


func get_destination(direction: String) -> String:
	if current_room == "entrance":
		if direction == "north":
			return "hall"
	elif current_room == "hall":
		if direction == "south":
			return "entrance"
		elif direction == "east":
			return "armory"
		elif direction == "west":
			return "library"
		elif direction == "north":
			return "treasury"
	elif current_room == "armory":
		if direction == "west":
			return "hall"
	elif current_room == "library":
		if direction == "east":
			return "hall"
	elif current_room == "treasury":
		if direction == "south":
			return "hall"
	return ""


func can_move(direction: String) -> bool:
	if current_room == "entrance":
		if direction == "north":
			return true
	elif current_room == "hall":
		if direction == "south" or direction == "east" or direction == "west" or direction == "north":
			return true
	elif current_room == "armory":
		if direction == "west":
			return true
	elif current_room == "library":
		if direction == "east":
			return true
	elif current_room == "treasury":
		if direction == "south":
			return true
	return false


func move(direction: String) -> bool:
	var dest: String = get_destination(direction)
	if dest != "":
		current_room = dest
		return true
	return false


func get_available_directions() -> Array[String]:
	if current_room == "entrance":
		return ["north"]
	elif current_room == "hall":
		return ["south", "east", "west", "north"]
	elif current_room == "armory":
		return ["west"]
	elif current_room == "library":
		return ["east"]
	elif current_room == "treasury":
		return ["south"]
	return []

class_name DungeonNavigator
extends RefCounted

var current_room: String = "entrance"

const ROOMS: Dictionary = {
	"entrance": {
		"name": "Ingresso della Fortezza",
		"exits": {"north": "hall"}
	},
	"hall": {
		"name": "Grande Atrio",
		"exits": {"south": "entrance", "east": "armory", "west": "library", "north": "treasury"}
	},
	"armory": {
		"name": "Armeria Reale",
		"exits": {"west": "hall"}
	},
	"library": {
		"name": "Antica Biblioteca",
		"exits": {"east": "hall"}
	},
	"treasury": {
		"name": "Sala del Tesoro",
		"exits": {"south": "hall"}
	}
}


func get_room_name() -> String:
	var room_data: Dictionary = ROOMS.get(current_room, {})
	return str(room_data.get("name", "Stanza Sconosciuta"))


func get_destination(direction: String) -> String:
	var room_data: Dictionary = ROOMS.get(current_room, {})
	var exits: Dictionary = room_data.get("exits", {})
	return str(exits.get(direction, ""))


func can_move(direction: String) -> bool:
	return get_destination(direction) != ""


func move(direction: String) -> bool:
	var dest: String = get_destination(direction)
	if dest == "":
		return false
	current_room = dest
	return true


func get_available_directions() -> Array[String]:
	var room_data: Dictionary = ROOMS.get(current_room, {})
	var exits: Dictionary = room_data.get("exits", {})
	var dirs: Array[String] = []
	for d in exits:
		dirs.append(str(d))
	return dirs
